import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const f=JSON.parse('{"title":"Software Update Manager","description":"","frontmatter":{},"headers":[],"relativePath":"plus/software-update-manager.md","filePath":"plus/software-update-manager.md"}'),n={name:"plus/software-update-manager.md"};function o(s,e,l,d,p,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="software-update-manager" tabindex="-1">Software Update Manager <a class="header-anchor" href="#software-update-manager" aria-label="Permalink to &quot;Software Update Manager&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Source-reviewed against TransferBook+ v0.7.26. Verify the installed release, company, permissions and configuration. Use authorized synthetic data for training. Commercial activation is not asserted.</p></div><h2 id="review-a-release" tabindex="-1">Review a release <a class="header-anchor" href="#review-a-release" aria-label="Permalink to &quot;Review a release&quot;">​</a></h2><ol><li>In Company Settings open Software Updates / System Updates, if permitted. Use Check for updates and inspect installed and candidate versions.</li><li>Review <a href="/release-notes/">Release Notes</a> and <a href="/changelog/">Changelog</a>. A higher version does not prove installation readiness. Inspect Advanced diagnostics if availability or schema compatibility is uncertain.</li><li>Before any authorized deployment, verify release signature, candidate identity, migration readiness, backup readability, recovery plan and preservation of company data, domains, credentials, provider settings and local themes.</li><li>The implemented protected staging updater can expose Update Now only when its gates permit. Demo and unapproved installations cannot initiate the protected release. Commercial customer installation and unattended production upgrades are not established by this guide.</li></ol><h2 id="confirm-installation" tabindex="-1">Confirm installation <a class="header-anchor" href="#confirm-installation" aria-label="Permalink to &quot;Confirm installation&quot;">​</a></h2><p>After explicit approval, submit an update only through the supported guarded process. Do not repeat while an update is requested or active. Confirm the server reports the verified new version; then reload the application. If progress appears stalled, inspect diagnostics and ask the platform administrator to check the receipt and service. Do not infer success from a request, browser timeout or a GitHub tag.</p><p>Verify installed version, service, schema, retained configuration and authorized application smoke tests. Use the approved recovery procedure if acceptance fails; never perform an unreviewed migration reversal.</p><p>See <a href="/installation/">Installation &amp; Deployment</a> and <a href="/security-privacy/">Security &amp; Privacy</a>.</p>',8)])])}const u=a(n,[["render",o]]);export{f as __pageData,u as default};
